"""Random power-law fields generated by Pencil Code (start.x only) -> kit format.

The Pencil run uses inituu = initaa = 'power_randomphase_hel' with initpower2 = initpower (pure power law),
cutoff = 0, relhel = 0, and lskip_projection = T for u (so u keeps its gradient part: a Level 1 input).
Pencil's shell spectrum is E(k) ~ k^initpower; with the kit's per-mode slope s (|u_hat|^2 ~ k^-s,
kit/fields.py) the mapping is

    u:          initpower    = 2 - s
    B = D x A:  initpower_aa = -s        (A has per-mode power k^(initpower_aa - 2))

For each VAR file: read u and A (float64), transpose Pencil's (z, y, x) to [comp, x, y, z], compute
B = kit.operators.curl(A), remove the mean of u (kit fields have zero mean; B has none), normalise u
and B to unit RMS, and build the target leray(u) with kit.projectors.leray in float64. Pencil's own
projection (lskip_projection = F) uses the exact k, not the FD6 symbol s(k), so it is never used as a
target. Saved as float32 npz: u, u_target, B, A (scaled with B), scales and the Pencil parameters.

Needs the kit environment plus the Pencil Code Python package and its imports, e.g.
    uv run --with h5py --with scipy --with matplotlib python data_prep/pencil_random_fields.py \\
        <run_dir> <out.npz> [--var-files VAR0] [--keep-mean]
"""
import argparse
import os
import sys
from pathlib import Path

import numpy as np
import torch

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
for _p in (os.path.join(os.environ.get("PENCIL_HOME", ""), "python"),
           os.path.expanduser("~/pencil-code/python")):
    if os.path.isdir(_p):
        sys.path.insert(0, _p)
        break
import pencil as pc  # noqa: E402

from kit.fields import make_field  # noqa: E402
from kit.metrics import divergence_residual  # noqa: E402
from kit.operators import SPATIAL, curl, wavenumbers  # noqa: E402
from kit.projectors import leray  # noqa: E402


def to_kit(a):
    """Pencil (comp, z, y, x) -> torch [1, comp, x, y, z], float64."""
    return torch.from_numpy(np.ascontiguousarray(np.transpose(np.asarray(a, dtype=np.float64), (0, 3, 2, 1))))[None]


def rms(v):
    return float(v.pow(2).mean(dim=(1, 2, 3, 4)).sqrt())


def shell_spectrum(v):
    """E(k) = sum of |FFT v|^2 over the integer shell |k| ~ k, for k = 0 .. max (sample 0)."""
    n = v.shape[-1]
    k = wavenumbers(n)
    shell = torch.sqrt(k.view(n, 1, 1) ** 2 + k.view(1, n, 1) ** 2 + k.view(1, 1, n) ** 2).round().long().flatten()
    p = torch.fft.fftn(v[0].double(), dim=SPATIAL).abs().pow(2).sum(dim=0).flatten()
    return torch.zeros(int(shell.max()) + 1, dtype=torch.float64).index_add_(0, shell, p)


def shell_slope(v, kmin, kmax):
    """Least-squares slope of log E(k) against log k over kmin <= k <= kmax."""
    e = shell_spectrum(v)
    k = torch.arange(len(e), dtype=torch.float64)
    m = (k >= kmin) & (k <= kmax)
    x, y = k[m].log(), e[m].log()
    x = x - x.mean()
    return float((x * (y - y.mean())).sum() / (x * x).sum())


def report(name, v, kmin, kmax, s_expected=None):
    sl = shell_slope(v, kmin, kmax)
    line = (f"  {name:9s} shell slope {sl:+7.3f} (per-mode s = {2 - sl:+6.3f})  "
            f"|D.v|/|Dv| float64 {float(divergence_residual(v)):.2e}  float32 {float(divergence_residual(v.float())):.2e}")
    if s_expected is not None:
        n = v.shape[-1]
        ref = make_field(n, s_expected, seed=0, dtype=torch.float64)
        line += f"   [kit make_field(s={s_expected:g}): shell slope {shell_slope(ref, kmin, kmax):+7.3f}]"
    print(line, flush=True)


def hydro_lskip_projection(datadir):
    """lskip_projection of hydro_init_pars (density has a namesake, so pc.read.param drops it)."""
    text = Path(datadir, "param.nml").read_text().upper()
    block = text.split("&HYDRO_INIT_PARS", 1)[1].split("/", 1)[0]
    return "LSKIP_PROJECTION=T" in block.replace(" ", "")


def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("run_dir")
    ap.add_argument("out", help="output .npz (one VAR file) or directory (several)")
    ap.add_argument("--var-files", nargs="+", default=["VAR0"])
    ap.add_argument("--keep-mean", action="store_true", help="keep the (random) mean mode Pencil puts in u")
    ap.add_argument("--kmin", type=float, default=2.0, help="slope fit range, lower end")
    ap.add_argument("--kmax", type=float, default=None, help="slope fit range, upper end (default N/4)")
    a = ap.parse_args()

    datadir = os.path.join(a.run_dir, "data")
    par = pc.read.param(datadir=datadir, quiet=True)
    p_u, p_aa = float(par.initpower), float(par.initpower_aa)
    meta = dict(seed0=int(par.seed0), initpower=p_u, initpower2=float(par.initpower2),
                initpower_aa=p_aa, initpower2_aa=float(par.initpower2_aa),
                relhel_uu=float(par.relhel_uu), relhel_aa=float(par.relhel_aa),
                lskip_projection=hydro_lskip_projection(datadir))
    print(f"{a.run_dir}: {meta}")
    if p_u != meta["initpower2"] or p_aa != meta["initpower2_aa"]:
        print("  WARNING: initpower2 != initpower, not a pure power law")
    s_u, s_b = 2.0 - p_u, 0.0 - p_aa
    print(f"  expected per-mode slopes: u s = {s_u:g}, B s = {s_b:g}")

    for vf in a.var_files:
        v = pc.read.var(datadir=datadir, var_file=vf, trimall=True, quiet=True)
        n = v.uu.shape[-1]
        assert v.uu.shape[1:] == (n, n, n), f"cubic grids only, got {v.uu.shape}"
        assert abs(float(v.x[0]) - (-np.pi + np.pi / n)) < 1e-10, "expected a cell-centred grid on [-pi, pi)"
        assert abs(float(v.x[1] - v.x[0]) - 2 * np.pi / n) < 1e-12, "expected a 2 pi box"
        kmax = a.kmax if a.kmax is not None else n / 4
        u, A = to_kit(v.uu), to_kit(v.aa)
        mean_u = u.mean(dim=SPATIAL, keepdim=True)
        print(f"  {vf}: N = {n}, mean(u)/rms(u) = {float(mean_u.norm()) / rms(u):.3f}"
              + ("  (kept)" if a.keep_mean else "  (removed)"))
        if not a.keep_mean:
            u = u - mean_u
        B = curl(A)
        su, sb = rms(u), rms(B)
        u, B, A = u / su, B / sb, A / sb
        target = leray(u)
        report("u", u, a.kmin, kmax, s_u)
        report("B", B, a.kmin, kmax, s_b)
        report("leray(u)", target, a.kmin, kmax)

        out = Path(a.out) if len(a.var_files) == 1 and a.out.endswith(".npz") else Path(a.out) / f"{vf}.npz"
        out.parent.mkdir(parents=True, exist_ok=True)
        f32 = lambda x: x[0].numpy().astype(np.float32)
        np.savez(out, u=f32(u), u_target=f32(target), B=f32(B), A=f32(A), scale_u=su, scale_B=sb,
                 t=float(v.t), var_file=vf, grid=n, run=os.path.basename(os.path.abspath(a.run_dir)), **meta)
        print(f"  -> {out}")


if __name__ == "__main__":
    main()
